from crewai import Task
 
from agent.invitation_agent import invitation_writer
 
 
def create_invitation_task(
    event_name,
    event_date,
    audience,
    idea_task,
    activity_task
):
 
    invitation_task = Task(
 
        description=(
 
            f"Write a short and friendly invitation "
            f"for the event: {event_name}."
 
            f"The event date is {event_date}."
 
            f"The target audience is {audience}."
 
            "Use the event theme generated by the Idea Generator."
 
            "Include the four activities prepared by the Activity Planner."
 
            "Make the invitation attractive and easy to understand."
 
            "Do not invent a venue."
 
            "If the venue is not provided, mention "
            "'Venue: To be confirmed'."
 
        ),
 
        expected_output=(
 
            "A short, friendly and attractive event invitation "
            "containing the event name, date, audience, "
            "event theme, activities and venue status."
 
        ),
 
        agent=invitation_writer,
 
        context=[
            idea_task,
            activity_task
        ]
    )
 
    return invitation_task